-- LeadFlow staging sanitizer — PREPARE. Run ONLY inside the temporary cleaning database. NEVER on production or staging.
-- Creates the safety marker (with a fresh random salt) and helper tables. Without these, sanitize.sql cannot change anything.
CREATE TABLE __staging_sanitize_marker (salt VARCHAR(64) NOT NULL, drift_ok TINYINT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE __column_map (t VARCHAR(128) NOT NULL, c VARCHAR(128) NOT NULL, PRIMARY KEY (t, c));
CREATE TABLE __name_first (i INT NOT NULL PRIMARY KEY, v VARCHAR(64) NOT NULL) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE __name_last (i INT NOT NULL PRIMARY KEY, v VARCHAR(64) NOT NULL) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE __streets (i INT NOT NULL PRIMARY KEY, v VARCHAR(64) NOT NULL) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE __team_words (i INT NOT NULL PRIMARY KEY, v VARCHAR(64) NOT NULL) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE __src_phone (`real` VARCHAR(320) NOT NULL PRIMARY KEY) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE __map_phone (`real` VARCHAR(320) NOT NULL PRIMARY KEY, fake VARCHAR(255) NOT NULL) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE __src_email (`real` VARCHAR(320) NOT NULL PRIMARY KEY) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE __map_email (`real` VARCHAR(320) NOT NULL PRIMARY KEY, fake VARCHAR(255) NOT NULL) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE __src_name (`real` VARCHAR(320) NOT NULL PRIMARY KEY) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE __map_name (`real` VARCHAR(320) NOT NULL PRIMARY KEY, fake VARCHAR(255) NOT NULL) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE __src_team (`real` VARCHAR(320) NOT NULL PRIMARY KEY) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE __map_team (`real` VARCHAR(320) NOT NULL PRIMARY KEY, fake VARCHAR(255) NOT NULL) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE __synthetic_conversations (scenario VARCHAR(32) NOT NULL, variant INT NOT NULL, n INT NOT NULL, history MEDIUMTEXT NOT NULL, last_text VARCHAR(1000) NOT NULL, last_role VARCHAR(16) NOT NULL, PRIMARY KEY (scenario, variant)) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
SELECT 'PREPARE COMPLETE' AS step, COUNT(*) AS mapped_columns FROM __column_map;
