INSERT INTO __synthetic_conversations (scenario, variant, n, history, last_text, last_role) VALUES ('new_booking', 0, 5, '[{"role":"user","content":"Hi, do you have anything this Friday for a 2 bed 2 bath?","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"Hi {first}! Yes, we have a 10am or 1pm arrival window this Friday. A standard clean for 2 bed / 2 bath is $165. Which works best?","ts":__TS1__,"synthetic":true},{"role":"user","content":"10am please","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"You''re booked for Friday with a 10–12 arrival window. We''ll text you when your team is on the way!","ts":__TS3__,"synthetic":true},{"role":"user","content":"Perfect, thank you","ts":__TS4__,"synthetic":true}]', 'Perfect, thank you', 'user'),
  ('new_booking', 1, 6, '[{"role":"user","content":"I''d like to book a deep clean before my parents visit next week","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"Happy to help, {first}! How many bedrooms and bathrooms, and which day works for you?","ts":__TS1__,"synthetic":true},{"role":"user","content":"3 bed 2 bath, Tuesday or Wednesday","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"Wednesday 9am is open. A deep clean for 3 bed / 2 bath is $310 including inside the fridge and oven. Shall I lock it in?","ts":__TS3__,"synthetic":true},{"role":"user","content":"Yes please book it","ts":__TS4__,"synthetic":true},{"role":"assistant","content":"Done! Wednesday 9–11am arrival. You''ll get a reminder the day before.","ts":__TS5__,"synthetic":true}]', 'Done! Wednesday 9–11am arrival. You''ll get a reminder the day before.', 'assistant'),
  ('new_booking', 2, 4, '[{"role":"user","content":"Can I get a cleaning tomorrow afternoon?","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"Hi {first}, we have one spot tomorrow at 2pm. Is it a standard clean? How many bedrooms?","ts":__TS1__,"synthetic":true},{"role":"user","content":"Standard, 1 bedroom 1 bath","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"Great, that''s $120. You''re booked for tomorrow 2–4pm arrival.","ts":__TS3__,"synthetic":true}]', 'Great, that''s $120. You''re booked for tomorrow 2–4pm arrival.', 'assistant'),
  ('quote', 0, 4, '[{"role":"user","content":"How much for a move-out clean? 2 bed 1 bath apartment","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"Hi {first}! A move-out clean for 2 bed / 1 bath is $245 and includes inside cabinets, fridge and oven. What date are you moving out?","ts":__TS1__,"synthetic":true},{"role":"user","content":"End of the month, let me check with my landlord","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"Sounds good, just reply here when you have a date and we''ll hold a spot for you.","ts":__TS3__,"synthetic":true}]', 'Sounds good, just reply here when you have a date and we''ll hold a spot for you.', 'assistant'),
  ('quote', 1, 6, '[{"role":"user","content":"What do you charge for a regular cleaning?","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"Hi {first}, it depends on the size of your home. How many bedrooms and bathrooms?","ts":__TS1__,"synthetic":true},{"role":"user","content":"4 bed 3 bath","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"A standard clean is $225, and every two weeks it drops to $195 per visit. Want me to send available times?","ts":__TS3__,"synthetic":true},{"role":"user","content":"Sure, send me some times","ts":__TS4__,"synthetic":true},{"role":"assistant","content":"We have Monday 9am, Tuesday 1pm or Thursday 10am. Any of those work?","ts":__TS5__,"synthetic":true}]', 'We have Monday 9am, Tuesday 1pm or Thursday 10am. Any of those work?', 'assistant'),
  ('quote', 2, 4, '[{"role":"user","content":"Quote for 3 bed 2.5 bath plus inside windows?","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"Hi {first}! That''s $195 for the clean plus $40 for inside windows, $235 total. Would you like to book?","ts":__TS1__,"synthetic":true},{"role":"user","content":"That''s a bit more than I expected, I''ll think about it","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"No problem at all. The quote is good for 14 days, just reply whenever you''re ready.","ts":__TS3__,"synthetic":true}]', 'No problem at all. The quote is good for 14 days, just reply whenever you''re ready.', 'assistant'),
  ('reschedule', 0, 4, '[{"role":"user","content":"Something came up, can we move Thursday''s cleaning?","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"Of course, {first}. We can do Friday at 10am or Monday at 1pm. Which is better?","ts":__TS1__,"synthetic":true},{"role":"user","content":"Monday 1pm","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"All set, you''re moved to Monday with a 1–3pm arrival window. Thursday is cancelled.","ts":__TS3__,"synthetic":true}]', 'All set, you''re moved to Monday with a 1–3pm arrival window. Thursday is cancelled.', 'assistant'),
  ('reschedule', 1, 4, '[{"role":"user","content":"Can the team come an hour later tomorrow?","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"Let me check with the team, {first}. One moment.","ts":__TS1__,"synthetic":true},{"role":"assistant","content":"Good news, they can arrive between 11am and 1pm instead. I''ve updated your booking.","ts":__TS2__,"synthetic":true},{"role":"user","content":"Thanks so much","ts":__TS3__,"synthetic":true}]', 'Thanks so much', 'user'),
  ('reschedule', 2, 4, '[{"role":"user","content":"I need to reschedule, I''ll be traveling next week","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"Safe travels, {first}! Would the following week work? We have Tuesday or Wednesday morning.","ts":__TS1__,"synthetic":true},{"role":"user","content":"Wednesday morning","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"Done, you''re booked for Wednesday 9–11am. Enjoy your trip!","ts":__TS3__,"synthetic":true}]', 'Done, you''re booked for Wednesday 9–11am. Enjoy your trip!', 'assistant'),
  ('cancellation', 0, 4, '[{"role":"user","content":"I need to cancel my cleaning on Saturday","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"Sorry to hear that, {first}. I''ve cancelled Saturday''s visit. Would you like to pick a new date?","ts":__TS1__,"synthetic":true},{"role":"user","content":"Not right now, thanks","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"No problem, we''re here whenever you need us.","ts":__TS3__,"synthetic":true}]', 'No problem, we''re here whenever you need us.', 'assistant'),
  ('cancellation', 1, 4, '[{"role":"user","content":"Please cancel my recurring cleanings, I''m moving out of the area","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"Thanks for letting us know, {first}, and best of luck with the move! Your recurring visits are cancelled. Need a move-out clean before you go?","ts":__TS1__,"synthetic":true},{"role":"user","content":"Actually yes, how much would that be?","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"For your home it''s $275. We have next Saturday open if that helps.","ts":__TS3__,"synthetic":true}]', 'For your home it''s $275. We have next Saturday open if that helps.', 'assistant'),
  ('cancellation', 2, 4, '[{"role":"user","content":"Cancel","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"Hi {first}, just to confirm, would you like to cancel your booking on the 14th?","ts":__TS1__,"synthetic":true},{"role":"user","content":"Yes","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"Your booking on the 14th has been cancelled. Thank you!","ts":__TS3__,"synthetic":true}]', 'Your booking on the 14th has been cancelled. Thank you!', 'assistant'),
  ('complaint', 0, 4, '[{"role":"user","content":"The team missed the kitchen floor and the bathroom mirror today","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"I''m really sorry, {first}. That''s not our standard. We''d like to send the team back to fix it free of charge. Would tomorrow morning work?","ts":__TS1__,"synthetic":true},{"role":"user","content":"Tomorrow at 9 is ok","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"Booked for 9am tomorrow at no charge. Thank you for telling us, and sorry again.","ts":__TS3__,"synthetic":true}]', 'Booked for 9am tomorrow at no charge. Thank you for telling us, and sorry again.', 'assistant'),
  ('complaint', 1, 4, '[{"role":"user","content":"The cleaner arrived almost 2 hours late","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"I apologize, {first}. There was a delay at the previous job and we should have let you know sooner. I''ve applied a $25 credit to your next clean.","ts":__TS1__,"synthetic":true},{"role":"user","content":"Ok thanks, please just text me next time","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"Absolutely, we''ve added a note to always text you if the team is running late.","ts":__TS3__,"synthetic":true}]', 'Absolutely, we''ve added a note to always text you if the team is running late.', 'assistant'),
  ('complaint', 2, 4, '[{"role":"user","content":"I think a vase was broken during the clean","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"I''m so sorry, {first}. Could you send a photo? We''ll make this right.","ts":__TS1__,"synthetic":true},{"role":"user","content":"Sent it in the email","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"Thank you, we received it. Our manager will call you today to arrange a replacement.","ts":__TS3__,"synthetic":true}]', 'Thank you, we received it. Our manager will call you today to arrange a replacement.', 'assistant'),
  ('recurring', 0, 4, '[{"role":"user","content":"Can we set up cleanings every two weeks?","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"Definitely, {first}! Every two weeks on Wednesdays at 10am works for your team. Your rate becomes $175 per visit.","ts":__TS1__,"synthetic":true},{"role":"user","content":"Great, start next Wednesday","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"You''re all set for every other Wednesday starting next week.","ts":__TS3__,"synthetic":true}]', 'You''re all set for every other Wednesday starting next week.', 'assistant'),
  ('recurring', 1, 4, '[{"role":"user","content":"Can I switch from monthly to weekly?","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"Of course, {first}. Weekly visits are $150 each. Same day and time as now?","ts":__TS1__,"synthetic":true},{"role":"user","content":"Yes same time","ts":__TS2__,"synthetic":true},{"role":"assistant","content":"Updated! You''re now weekly on Mondays at 1pm.","ts":__TS3__,"synthetic":true}]', 'Updated! You''re now weekly on Mondays at 1pm.', 'assistant'),
  ('recurring', 2, 3, '[{"role":"user","content":"Can I skip next week''s recurring clean?","ts":__TS0__,"synthetic":true},{"role":"assistant","content":"No problem, {first}. Next week is skipped and your regular schedule resumes the week after.","ts":__TS1__,"synthetic":true},{"role":"user","content":"Perfect","ts":__TS2__,"synthetic":true}]', 'Perfect', 'user'),
